import { Table, StringColumn, GuidColumn } from '@servicenow/sdk/core'

export const sc_ordered_item_link = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    extends: 'sys_metadata',
    label: 'Ordered Item Link',
    name: 'sc_ordered_item_link',
    schema: {
        name: StringColumn({
            label: [
                {
                    hint: 'Name of this link for reference',
                    label: 'Name',
                    plural: 'Names',
                    language: 'en',
                },
            ],
            maxLength: 100,
        }),
        link_text: StringColumn({
            label: 'Link text',
            maxLength: 100,
        }),
        link_url: StringColumn({
            label: 'Link URL',
            maxLength: 255,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        target: StringColumn({
            default: '_blank',
            choices: {
                _blank: {
                    label: 'New Window/Tab',
                    sequence: 2,
                },
                internal: {
                    label: 'Within Catalog',
                    sequence: 1,
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'Target',
        }),
    },
})
